"""Local intent frames: actor, transfer, desired result and context. No service words."""
import re
from message_classification import positive

def extract(text):
    s=text.lower().replace('ё','е').replace('\n',' ').replace('\r',' ')
    patterns={
      'seek_executor':r'кто\s+(?:возьмется|свободен|исправит|посмотрит|готов\s+помочь)|у\s+кого\s+есть\s+окно|кому\s+можно\s+отдать|готовы\s+обсудить.{0,90}с\s+исполнител|исполнителя\s+выбираем|есть\s+задача|есть\s+заказ|отдам|отдаю\s+на\s+аутсорс|рассмотрим\s+предложения|есть\s+работа',
      'desired_action':r'\b(?:надо|нужн|хотим|планируем)\b|\b(?:переделать|собрать|оформить|нарисовать|сверстать|перенести|поправить)\b',
      'incoming_condition':r'если\s+(?:вы\s+)?умеете.{0,100}(?:напишите|пишите).{0,70}(?:есть\s+(?:проект|заказ|задача))',
      'outgoing_condition':r'если\s+(?:кому.to\s+)?(?:вам\s+)?нуж\w*.{0,120}(?:пишите|напишите|обращайтесь)|кому\s+нуж\w*.{0,100}(?:сделаю|помогу)|ищете.{0,100}вы\s+его\s+нашли',
      'seek_work':r'ищу\s+(?:проекты|заказчиков|клиентов|работу)|нужны\s+клиенты|возьму.{0,55}в\s+работу|готов\s+сотрудничать.{0,60}как\s+|освободилось\s+место.{0,50}разработк|продаю\s+базу\s+заказчик',
      'outgoing_sales':r'продажи\s+ваши.{0,25}разработка\s+наша|отдаю\s+процент\s+за\s+клиента',
      'incoming_sales':r'продажи\s+наши.{0,25}разработка\s+ваша|возьмет\s+разработку.{0,30}продажи\s+наши',
      'recurring':r'на\s+поток\s+проект|в\s+пул\s+подрядчик|постоянн\w*\s+проектн\w*\s+(?:задач|подряд)|постоянн\w*\s+поток\s+заказ|будем\s+передавать|на\s+постоянн\w*\s+подряд|субподряд|в\s+подрядку|поток\s+задач|на\s+постоянн\w*\s+сотруднич',
      'finite_transfer':r'передадим|отдам|отдать|есть\s+заказ',
      'instruction_question':r'как\s+(?:самому|самостоятельно)|сколько\s+(?:сейчас\s+)?стоит',
      'narrative':r'пример\s+(?:плохого\s+)?объявления|мне\s+каждый\s+день\s+пишут|вчера\s+обсуждали|как\s+искать\s+разработчик',
      'actual_relay':r'знакомому\s+нуж|клиент\s+прислал|ищу.{0,15}кому\s+передать|контакты\s+передам',
      'independent':r'но\s+(?:сейчас\s+)?(?:ищ|нуж)|отдельно\s+(?:ищ|нуж)|для\s+(?:своего|моего|клиентского)\s+(?:проекта|лендинга|сайта)',
      'separable':r'исполнители\s+могут\s+быть\s+разные|можно\s+выбрать\s+одно\s+направление|можно\s+взять\s+только|можно\s+самостоятельно\s+выбирать|универсалом\s+быть\s+не\s+нужно',
      'renewal':r'снова\s+ищем|предыдущий\s+исполнитель\s+отказался',
      'closed':r'разработчика\s+нашли|(?:задач\w*|проект|сайт)\s+закрыли|\bотбой\b|пока\s+заморозили|\bзакрыто\b'}
    patterns['seek_executor']+=r'|есть\s+кто|нужен\s+специалист|ищем\s+исполнителя\s+разобраться|отдельно\s+дизайнер\w*'
    patterns['outgoing_condition']+=r'|у\s+кого.{0,100}\?\s*помогу\s+исправить'
    patterns['outgoing_sales']=r'продажи\s+ваши.{0,50}разработка(?:\s+\w+){0,3}\s+наша|отдаю\s+процент\s+за\s+клиента'
    patterns['incoming_sales']=r'продажи\s+наши.{0,50}разработка(?:\s+\w+){0,3}\s+ваша|возьмет\s+разработку.{0,30}продажи\s+наши'
    patterns['reciprocal']=r'обмениваться\s+клиентами'
    return {k:positive(p,s) for k,p in patterns.items()}
